16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.util.*;
25	
26	/**
27	 * Simple JavaBean domain object representing an owner.
28	 *
29	 * @author Ken Krebs
30	 * @author Juergen Hoeller
31	 * @author Sam Brannen
32	 * @author Michael Isvy
33	 */
34	@Entity
35	@Table(name = "owners")
36	public class Owner extends Person {
37	    @Column(name = "address")
38	    @NotEmpty
39	    private String address;
40	
41	    @Column(name = "city")
42	    @NotEmpty
43	    private String city;
44	
45	    @Column(name = "telephone")
46	    @NotEmpty
47	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be E.164 form: '+' followed by 8 to 15 digits")
48	    private String telephone;
49	
50	    @Column(name = "email")
51	    private String email;
52	
53	    @Column(name = "registration_date", columnDefinition = "DATE")
54	    private java.time.LocalDate registrationDate;
55	
56	    @Column(name = "customer_code")
57	    private String customerCode;
58	
59	    @Column(name = "household_id")
60	    private String householdId;
61	
62	    @Column(name = "namesake_count")
63	    private Integer namesakeCount;
64	
65	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
66	    private Set<Pet> pets;
67	
68	    public String getAddress() {
69	        return this.address;
70	    }
71	
72	    public void setAddress(String address) {
73	        this.address = address;
74	    }
75	
76	    public String getCity() {
77	        return this.city;
78	    }
79	
80	    public void setCity(String city) {
81	        this.city = city;
82	    }
83	
84	    public String getTelephone() {
85	        return this.telephone;
86	    }
87	
88	    public void setTelephone(String telephone) {
89	        this.telephone = telephone;
90	    }
91	
92	    public String getEmail() {
93	        return this.email;
94	    }
95	
96	    public void setEmail(String email) {
97	        this.email = email;
98	    }
99	
100	    public java.time.LocalDate getRegistrationDate() {
101	        return this.registrationDate;
102	    }
103	
104	    public void setRegistrationDate(java.time.LocalDate registrationDate) {
105	        this.registrationDate = registrationDate;
106	    }
107	
108	    public String getCustomerCode() {
109	        return this.customerCode;
110	    }
111	
112	    public void setCustomerCode(String customerCode) {
113	        this.customerCode = customerCode;
114	    }
115	
116	    public String getHouseholdId() {
117	        return this.householdId;
118	    }
119	
120	    public void setHouseholdId(String householdId) {
121	        this.householdId = householdId;
122	    }
123	
124	    public Integer getNamesakeCount() {
125	        return this.namesakeCount;
126	    }
127	
128	    public void setNamesakeCount(Integer namesakeCount) {
129	        this.namesakeCount = namesakeCount;
130	    }
131	
132	    protected Set<Pet> getPetsInternal() {
133	        if (this.pets == null) {
134	            this.pets = new HashSet<>();
135	        }
136	        return this.pets;
137	    }
138	
139	    protected void setPetsInternal(Set<Pet> pets) {
140	        this.pets = pets;
141	    }
142	
143	    public List<Pet> getPets() {
144	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
145	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
146	        return Collections.unmodifiableList(sortedPets);
147	    }
148	
149	    public void setPets(List<Pet> pets) {
150	        this.pets = new HashSet<>(pets);
151	    }
152	
153	    public void addPet(Pet pet) {
154	        getPetsInternal().add(pet);
155	        pet.setOwner(this);
156	    }
157	
158	    /**
159	     * Return the Pet with the given name, or null if none found for this Owner.
160	     *
161	     * @param name to test
162	     * @return true if pet name is already in use
163	     */
164	    public Pet getPet(String name) {
165	        return getPet(name, false);
166	    }
167	
168	    /**
169	     * Return the Pet with the given name, or null if none found for this Owner.
170	     *
171	     * @param name to test
172	     * @return true if pet name is already in use
173	     */
174	    public Pet getPet(String name, boolean ignoreNew) {
175	        name = name.toLowerCase();
176	        for (Pet pet : getPetsInternal()) {
177	            if (!ignoreNew || !pet.isNew()) {
178	                String compName = pet.getName();
179	                compName = compName.toLowerCase();
180	                if (compName.equals(name)) {
181	                    return pet;
182	                }
183	            }
184	        }
185	        return null;
186	    }
187	
188	    public Pet getPet(Integer petId) {
189	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
190	    }
191	
192	    @Override
193	    public String toString() {
194	        return new ToStringCreator(this)
195	
196	            .append("id", this.getId())
197	            .append("new", this.isNew())
198	            .append("lastName", this.getLastName())
199	            .append("firstName", this.getFirstName())
200	            .append("address", this.address)
201	            .append("city", this.city)
202	            .append("telephone", this.telephone)
203	            .toString();
204	    }
205	}
