1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.ArrayList;
7	import java.util.List;
8	import java.util.Locale;
9	
10	import net.officefloor.plugin.variable.Val;
11	import org.springframework.samples.petclinic.model.Owner;
12	import org.springframework.samples.petclinic.repository.OwnerRepository;
13	import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;
14	
15	/**
16	 * Enforces the household rule on create. An owner sharing an existing owner's last name and
17	 * address (compared in the normalized address form, see {@link AddressNormalizer}) is a 409 Conflict — unless the
18	 * request opted in with {@code sharesHousehold} true. When it did opt in, the two are allowed to
19	 * share a household and are given the same stable {@code householdId}: it is stamped on the new
20	 * owner and on every existing member of that household. Runs after {@link BuildOwner}.
21	 */
22	public class CheckOwnerHouseholdUnique {
23	
24	    public void service(@Val Owner owner, @Val Boolean sharesHousehold,
25	            OwnerRepository ownerRepository) throws DuplicateHouseholdException {
26	        String lastName = key(owner.getLastName());
27	        String address = AddressNormalizer.normalize(owner.getAddress());
28	        List<Owner> household = new ArrayList<>();
29	        for (Owner existing : ownerRepository.findAll()) {
30	            if (existing.getId() != null && existing.getId().equals(owner.getId())) {
31	                continue; // same record (e.g. re-save), not a conflict
32	            }
33	            if (lastName.equals(key(existing.getLastName()))
34	                    && address.equals(AddressNormalizer.normalize(existing.getAddress()))) {
35	                household.add(existing);
36	            }
37	        }
38	        if (household.isEmpty()) {
39	            return; // no existing owner at this last name + address
40	        }
41	        if (!Boolean.TRUE.equals(sharesHousehold)) {
42	            throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
43	        }
44	        // Explicitly allowed to share: assign the same stable household identifier to all members.
45	        String householdId = householdId(lastName, address, household);
46	        owner.setHouseholdId(householdId);
47	        for (Owner member : household) {
48	            if (!householdId.equals(member.getHouseholdId())) {
49	                member.setHouseholdId(householdId);
50	                ownerRepository.save(member);
51	            }
52	        }
53	    }
54	
55	    /**
56	     * The household's stable shared identifier: reuse the id an existing member already carries
57	     * (so a household keeps one value over time); otherwise derive it deterministically from the
58	     * normalized last name and address, so independent joiners compute the same value.
59	     */
60	    private static String householdId(String lastName, String address, List<Owner> household) {
61	        for (Owner member : household) {
62	            String existing = member.getHouseholdId();
63	            if (existing != null && !existing.isBlank()) {
64	                return existing;
65	            }
66	        }
67	        return "H-" + sha256Hex(lastName + "\n" + address).substring(0, 12).toUpperCase(Locale.ROOT);
68	    }
69	
70	    private static String sha256Hex(String value) {
71	        try {
72	            byte[] digest = MessageDigest.getInstance("SHA-256")
73	                    .digest(value.getBytes(StandardCharsets.UTF_8));
74	            StringBuilder sb = new StringBuilder(digest.length * 2);
75	            for (byte b : digest) {
76	                sb.append(String.format("%02x", b));
77	            }
78	            return sb.toString();
79	        }
80	        catch (NoSuchAlgorithmException e) {
81	            throw new IllegalStateException("SHA-256 not available", e);
82	        }
83	    }
84	
85	    /** Comparison key: lower-cased, with leading/trailing and repeated whitespace collapsed. */
86	    private static String key(String value) {
87	        if (value == null) {
88	            return "";
89	        }
90	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
91	    }
92	}
